Address address = Address.newInstance().withStreet('12 Lake Road').withCity('Port Alsworth').withState('Alaska').withStateCode('AK').withPostalCode('99653').withCountry('United States').withCountryCode('US').withLatitude(60.2027).withLongitude(-154.3128).withGeocodeAccuracy('Zip');
System.assertEquals('12 Lake Road', address.getStreet());
System.assertEquals('Port Alsworth', address.getCity());
System.assertEquals('Alaska', address.getState());
System.assertEquals('AK', address.getStateCode());
System.assertEquals('99653', address.getPostalCode());
System.assertEquals('United States', address.getCountry());
System.assertEquals('US', address.getCountryCode());
System.assertEquals(60.2027, address.getLatitude());
System.assertEquals(-154.3128, address.getLongitude());
System.assertEquals('Zip', address.getGeocodeAccuracy());
System.assert(address.getDistance(Location.newInstance(60.0, -154.0), 'mi') > 0);

